    "categorical-cross-entropy-loss-markdown-code-5": "#include <cuda_runtime.h>\n\n// logits, true_labels, loss are device pointers\nextern \"C\" void solve(const float* logits, const int* true_labels, float* loss, int N, int C) {}",
